V['bb01f9ce'] = ('exclude', '**檢索雜訊（兒童肥胖社區介入）**：零肥胖方案——葡萄牙五個市鎮過重國小學童之社區介入（266 名 6–10 歲過重兒童，六個月）。族群軸：6–10 歲兒童，年齡遠低於契約下限；運動型態軸：**身體活動諮商，無結構化運動方案**；介入軸：**營養與活動諮商，非碳水給予**；結果軸：腰圍、身體質量指數與飲食行為。四軸皆出局，排除。附帶記錄：⚠️ **並記其為本頁第四筆行為介入試驗**（另三筆為 `df464500` 孕期諮商、`7e111039` 同儕支持、`834124af` 補充品試驗）——**🚨 本頁行為介入密度為近期最高**；檢索雜訊累計第 801 筆。')

rows = json.load(open('.scratch/_p275_ids.json', encoding='utf-8'))
ids = {r['short']: r['candidateId'] for r in rows}
assert set(V) == set(ids), (sorted(set(ids) - set(V)), sorted(set(V) - set(ids)))
assert list(V.keys()) == [r['short'] for r in rows], \
    ('條目順序與 worksheet 不符', list(V.keys())[:5], [r['short'] for r in rows][:5])
out = [{'candidateId': ids[r['short']],
        'opinion': V[r['short']][0],
        'reason': V[r['short']][1]} for r in rows]
json.dump(out, open('.scratch/std_p275.json', 'w', encoding='utf-8'),
          ensure_ascii=False, indent=1)
print('wrote %d entries; order matches worksheet' % len(out))
